.aui-root .hljs {
  display: block;
  overflow-x: auto;
  padding: 0.5em;
  background: #011627;
  color: #d6deeb;
}

/* General Purpose */

.aui-root .hljs-keyword {
  color: #c792ea;
  font-style: italic;
}

.aui-root .hljs-built_in {
  color: #addb67;
  font-style: italic;
}

.aui-root .hljs-type {
  color: #82aaff;
}

.aui-root .hljs-literal {
  color: #ff5874;
}

.aui-root .hljs-number {
  color: #F78C6C;
}

.aui-root .hljs-regexp {
  color: #5ca7e4;
}

.aui-root .hljs-string {
  color: #ecc48d;
}

.aui-root .hljs-subst {
  color: #d3423e;
}

.aui-root .hljs-symbol {
  color: #82aaff;
}

.aui-root .hljs-class {
  color: #ffcb8b;
}

.aui-root .hljs-function {
  color: #82AAFF;
}

.aui-root .hljs-title {
  color: #DCDCAA;
  font-style: italic;
}

.aui-root .hljs-params {
  color: #7fdbca;
}

/* Meta */

.aui-root .hljs-comment {
  color: #637777;
  font-style: italic;
}

.aui-root .hljs-doctag {
  color: #7fdbca;
}

.aui-root .hljs-meta {
  color: #82aaff;
}

.aui-root .hljs-meta-keyword {
  color: #82aaff;
}

.aui-root .hljs-meta-string {
  color: #ecc48d;
}

/* Tags, attributes, config */

.aui-root .hljs-section {
  color: #82b1ff;
}

.aui-root .hljs-tag,
.aui-root .hljs-name,
.aui-root .hljs-builtin-name {
  color: #7fdbca;
}

.aui-root .hljs-attr {
  color: #7fdbca;
}

.aui-root .hljs-attribute {
  color: #80cbc4;
}

.aui-root .hljs-variable {
  color: #addb67;
}

/* Markup */

.aui-root .hljs-bullet {
  color: #d9f5dd;
}

.aui-root .hljs-code {
  color: #80CBC4;
}

.aui-root .hljs-emphasis {
  color: #c792ea;
  font-style: italic;
}

.aui-root .hljs-strong {
  color: #addb67;
  font-weight: bold;
}

.aui-root .hljs-formula {
  color: #c792ea;
}

.aui-root .hljs-link {
  color: #ff869a;
}

.aui-root .hljs-quote {
  color: #697098;
  font-style: italic;
}

/* CSS */

.aui-root .hljs-selector-tag {
  color: #ff6363;
}

.aui-root .hljs-selector-id {
  color: #fad430;
}

.aui-root .hljs-selector-class {
  color: #addb67;
  font-style: italic;
}

.aui-root .hljs-selector-attr,
.aui-root .hljs-selector-pseudo {
  color: #c792ea;
  font-style: italic;
}

/* Templates */

.aui-root .hljs-template-tag {
  color: #c792ea;
}

.aui-root .hljs-template-variable {
  color: #addb67;
}

/* diff */

.aui-root .hljs-addition {
  color: #addb67ff;
  font-style: italic;
}

.aui-root .hljs-deletion {
  color: #EF535090;
  font-style: italic;
}

