.aui-root .container{
  width: 100%;
}

@media (min-width: 640px){
  .aui-root .container{
    max-width: 640px;
  }
}

@media (min-width: 768px){
  .aui-root .container{
    max-width: 768px;
  }
}

@media (min-width: 1024px){
  .aui-root .container{
    max-width: 1024px;
  }
}

@media (min-width: 1280px){
  .aui-root .container{
    max-width: 1280px;
  }
}

@media (min-width: 1536px){
  .aui-root .container{
    max-width: 1536px;
  }
}

.aui-root .prose{
  color: #4a5568;
  max-width: 65ch;
}

.aui-root .prose [class~="lead"]{
  color: #718096;
  font-size: 1.25em;
  line-height: 1.6;
  margin-top: 1.2em;
  margin-bottom: 1.2em;
}

.aui-root .prose a{
  color: #1a202c;
  text-decoration: underline;
  font-weight: 500;
}

.aui-root .prose strong{
  color: #1a202c;
  font-weight: 600;
}

.aui-root .prose ol[type="A"]{
  --list-counter-style: upper-alpha;
}

.aui-root .prose ol[type="a"]{
  --list-counter-style: lower-alpha;
}

.aui-root .prose ol[type="A" s]{
  --list-counter-style: upper-alpha;
}

.aui-root .prose ol[type="a" s]{
  --list-counter-style: lower-alpha;
}

.aui-root .prose ol[type="I"]{
  --list-counter-style: upper-roman;
}

.aui-root .prose ol[type="i"]{
  --list-counter-style: lower-roman;
}

.aui-root .prose ol[type="I" s]{
  --list-counter-style: upper-roman;
}

.aui-root .prose ol[type="i" s]{
  --list-counter-style: lower-roman;
}

.aui-root .prose ol[type="1"]{
  --list-counter-style: decimal;
}

.aui-root .prose ol > li{
  position: relative;
  padding-left: 1.75em;
}

.aui-root .prose ol > li::before{
  content: counter(list-item, var(--list-counter-style, decimal)) ".";
  position: absolute;
  font-weight: 400;
  color: #a0aec0;
  left: 0;
}

.aui-root .prose ul > li{
  position: relative;
  padding-left: 1.75em;
}

.aui-root .prose ul > li::before{
  content: "";
  position: absolute;
  background-color: #e2e8f0;
  border-radius: 50%;
  width: 0.375em;
  height: 0.375em;
  top: calc(0.875em - 0.1875em);
  left: 0.25em;
}

.aui-root .prose hr{
  border-color: #edf2f7;
  border-top-width: 1px;
  margin-top: 3em;
  margin-bottom: 3em;
}

.aui-root .prose blockquote{
  font-weight: 500;
  font-style: italic;
  color: #1a202c;
  border-left-width: 0.25rem;
  border-left-color: #edf2f7;
  quotes: "\201C""\201D""\2018""\2019";
  margin-top: 1.6em;
  margin-bottom: 1.6em;
  padding-left: 1em;
}

.aui-root .prose blockquote p:first-of-type::before{
  content: open-quote;
}

.aui-root .prose blockquote p:last-of-type::after{
  content: close-quote;
}

.aui-root .prose h1{
  color: #1a202c;
  font-weight: 800;
  font-size: 2.25em;
  margin-top: 0;
  margin-bottom: 0.8888889em;
  line-height: 1.1111111;
}

.aui-root .prose h2{
  color: #1a202c;
  font-weight: 700;
  font-size: 1.5em;
  margin-top: 2em;
  margin-bottom: 1em;
  line-height: 1.3333333;
}

.aui-root .prose h3{
  color: #1a202c;
  font-weight: 600;
  font-size: 1.25em;
  margin-top: 1.6em;
  margin-bottom: 0.6em;
  line-height: 1.6;
}

.aui-root .prose h4{
  color: #1a202c;
  font-weight: 600;
  margin-top: 1.5em;
  margin-bottom: 0.5em;
  line-height: 1.5;
}

.aui-root .prose figure figcaption{
  color: #a0aec0;
  font-size: 0.875em;
  line-height: 1.4285714;
  margin-top: 0.8571429em;
}

.aui-root .prose code{
  color: #1a202c;
  font-weight: 600;
  font-size: 0.875em;
}

.aui-root .prose code::before{
  content: "`";
}

.aui-root .prose code::after{
  content: "`";
}

.aui-root .prose a code{
  color: #1a202c;
}

.aui-root .prose pre{
  color: #edf2f7;
  background-color: #1a202c;
  overflow-x: auto;
  font-size: 0.875em;
  line-height: 1.7142857;
  margin-top: 1.7142857em;
  margin-bottom: 1.7142857em;
  border-radius: 0.375rem;
  padding-top: 0.8571429em;
  padding-right: 1.1428571em;
  padding-bottom: 0.8571429em;
  padding-left: 1.1428571em;
}

.aui-root .prose pre code{
  background-color: transparent;
  border-width: 0;
  border-radius: 0;
  padding: 0;
  font-weight: 400;
  color: inherit;
  font-size: inherit;
  font-family: inherit;
  line-height: inherit;
}

.aui-root .prose pre code::before{
  content: none;
}

.aui-root .prose pre code::after{
  content: none;
}

.aui-root .prose table{
  width: 100%;
  table-layout: auto;
  text-align: left;
  margin-top: 2em;
  margin-bottom: 2em;
  font-size: 0.875em;
  line-height: 1.7142857;
}

.aui-root .prose thead{
  color: #1a202c;
